ROOT=Path(__file__).resolve().parents[1];D=ROOT/'dist';D.mkdir(exist_ok=True)
SITE_ORIGIN=os.environ.get('SITE_ORIGIN','http://127.0.0.1:4173').rstrip('/')
def esc(s):return html.escape(str(s))
def link(url,label,cls=''):return f'<a class="{cls}" href="{url}">{label}</a>'
def button(url,label,secondary=False):return link(url,label+' <span aria-hidden="true">↗</span>','button secondary' if secondary else 'button')
def tag(t):return f'<span class="eyebrow">{t}</span>'
def section(k,title,body,cls='',id=''):
 key=k.upper()
 material=('lilac' if any(w in key for w in ['QUESTIONS','BEFORE WE BEGIN']) else 'clay' if any(w in key for w in ['BUYING GROUP','RELATED','STARTING','VISION','WHERE WE ARE']) else 'celadon' if any(w in key for w in ['SOURCE','INPUT','SCHEMA','CONTRACT','CASE','SHARED WORKBENCH']) else 'ochre' if any(w in key for w in ['MEASURE','QUOTABLE','SCORECARD','STOP CONDITIONS']) else 'sand' if any(w in key for w in ['WORKFLOW','STAGES','ENGAGEMENT','RESPONSIBILITIES','CHECKLIST']) else 'paper')
 return f'<section class="section {cls}" data-material="{material}"'+(f' id="{id}"' if id else '')+'><div class="wrap">'+tag(k)+f'<h2>{title}</h2>{body}</div></section>'
def cta(module=None):
 url='/request-evaluation/?offer='+(module['slug'] if module else 'undecided')
 context=('A proposed '+module['name']+' evaluation' if module else 'ONE DISTRICT. ONE DEFINED TEST.')
 return '<section class="closing closing-v3" id="next-step" aria-labelledby="closing-title"><div class="wrap closing-grid"><div class="closing-copy">'+tag(context)+'<h2 id="closing-title">One district.<br><em>A clearer next step.</em></h2><p>Bring your water-loss question. Define the evidence, the people and the criteria for a paid evaluation.</p><a class="closing-protocol" href="/evaluation/">Read the pilot protocol <span aria-hidden="true">→</span></a><div class="closing-prep"><span>Before real data</span><p>Named operator · Data owner · Crew lead<br>Procurement and legal permission</p></div></div><div class="closing-paths"><article class="engagement-path"><span class="path-label">01 / FOR YOUR UTILITY</span><h3>Define a paid pilot.</h3><p>Start with one module, one district and an agreed comparison method.</p>'+button(url,'Request a paid evaluation')+'<small>Local request preview · Nothing is sent</small></article><article class="exploration-path"><div><span class="path-label">02 / EXPLORE FIRST</span><h3>See the evidence.</h3><p>Open a case with sources, uncertainty and a human review.</p></div><a href="/demo/cases/demo-c01/" class="demo-path-link">Explore the synthetic demo <span aria-hidden="true">↗</span></a><small>Synthetic data · No account needed</small></article></div></div></section>'
def badge(state='suspected',label=None):return f'<span class="badge {state}">{esc(label or state.replace("-"," "))}</span>'
def chart(pressure=False):
 kind='pressure' if pressure else 'flow'
 label='Pressure in bar; one missing sample at 02:30 UTC' if pressure else 'Inlet flow in cubic meters per hour'
 return '<div class="measurement-chart"><canvas data-chart="'+kind+'" role="img" aria-label="Synthetic '+label+'"></canvas></div><p class="chart-footnote">'+('7 / 8 observations · gap at 02:30 retained' if pressure else '20 Oct 2026 · eight half-hour observations')+'</p>'
def district_map():
 return '''<svg class="district-map" viewBox="0 0 640 410" role="img" aria-label="Fictional district D07 schematic. C01 suspected; C04 field-confirmed simulated historical example. Not a real asset map."><defs><pattern id="map-grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#c7cec6" stroke-width=".5"/></pattern></defs><rect width="640" height="410" fill="#e7ece5"/><rect width="640" height="410" fill="url(#map-grid)"/><path d="M440 -10Q390 80 452 155T460 300T480 430" fill="none" stroke="#c3d6cf" stroke-width="55"/><g fill="#d7dccd" stroke="#b8c4b5"><path d="M58 52H172V122H58ZM225 56H360V105H225ZM90 200H172V320H90ZM230 180H355V260H230ZM520 70H590V170H520ZM525 270H610V345H525Z"/></g><g stroke="#fcfbf7" stroke-width="17" fill="none"><path d="M30 155H610M200 20V390M40 350H620M495 20V390"/></g><path d="M40 154H495V350H200V154M200 250H355" stroke="#526d61" stroke-width="4" fill="none"/><path d="M355 250H407" stroke="#526d61" stroke-dasharray="5 7" stroke-width="4" fill="none"/><circle cx="200" cy="154" r="25" fill="#a64f35" opacity=".12"/><path d="M200 141L213 154L200 167L187 154Z" fill="#a64f35"/><circle cx="495" cy="350" r="9" fill="#24533f"/><g font-family="Manrope,Arial" font-size="13" fill="#182f2c"><rect x="230" y="120" width="153" height="65" rx="4" fill="#fcfbf7"/><text x="243" y="145">C01 · Suspected</text><text x="243" y="167" font-size="10">Confirmation needed</text><text x="347" y="380" font-size="11">C04 · verified, simulated</text><text x="30" y="395" font-size="10">DEMO-D07 · FICTIONAL SCHEMATIC</text><text x="30" y="30" font-size="10">FLOW / PRESSURE / ACOUSTIC</text></g></svg>'''
def district_visual():
 return '<figure class="survey-preview"><img src="/assets/atlas-district-v2-transparent.png" width="1254" height="1254" alt="Illustrative district survey with green underground water main"><figcaption><span>DEMO-D07 / FICTIONAL DISTRICT</span><strong>Evidence, in context.</strong><p>C01 suspected · Confirmation needed<br>C04 field-confirmed · Simulated history</p></figcaption></figure>'
def artifact(kind='proof'):
 head='<div class="artifact-head"><span>DEMO · SIMULATED DATA</span><span>DEMO-D07 / 20 OCT 2026</span></div>'
 if kind=='ledger':body='<div class="artifact-title">The balance, before the diagnosis.</div>'+''.join(f'<div class="ledger-row"><span>{a}</span><strong>{b}</strong></div>' for a,b in [('System input','2,700 m³'),('Billed authorized','2,460 m³'),('Unbilled authorized','40 m³'),('Unresolved residual','200 m³'),('Non-revenue water','240 m³')])+'<p class="small">19 Oct 2026 full-day accounting window. The residual is not verified leakage.</p>'
 elif kind=='trend':body='<div class="artifact-title">A pattern. With an exception.</div><div class="chart-label">Inlet flow / m³/h · illustrative</div>'+chart()+'<div class="chart-label">Pressure / bar · illustrative</div>'+chart(True)
 elif kind=='route':body=district_visual()+'<div class="ledger-row"><span>Draft next step</span><strong>Utility review</strong></div><p class="small">DEMO Nia Cole · due 22 Oct 09:00 UTC. No dispatch or route optimization claim.</p>'
 elif kind=='report':body='<div class="report-cover">'+tag('ILLUSTRATIVE REVIEW PACKET')+'<h3>Evidence stays<br>with the decision.</h3>'+badge('suspected','Suspected · confirmation needed')+'<p>DEMO-C01 / Version 1.0</p><hr><div class="ledger-row"><span>Reviewer</span><strong>DEMO Tara Sen</strong></div><div class="ledger-row"><span>Sources</span><strong>DEMO-E01–E07</strong></div><p class="small">No field confirmation or repair record exists for this example case.</p></div>'
 else:body='<div class="artifact-title">One case. Competing explanations.</div>'+''.join(f'<div class="source-row"><span class="source-index">0{i+1}</span><div><strong>{a}</strong><p>{b}</p></div><span class="quality">{q}</span></div>' for i,(a,b,q) in enumerate([('Flow change','110.5 → 139.5 m³/h · illustrative','Observed'),('Pressure evidence','7 of 8 samples; 02:30 missing','Partial'),('Acoustic observation','Persistent noise; cause unestablished','Inconclusive'),('Meter alternative','Calibration flag unresolved','Retained')]))+'<div class="review-strip">◇ Suspected <span>Field confirmation needed</span></div>'
 return '<div class="artifact">'+head+body+'</div>'
def faq(items=FAQ):return '<div class="faq">'+''.join(f'<details><summary>{esc(q)}<span aria-hidden="true">+</span></summary><p>{esc(a)}</p></details>' for q,a in items)+'</div>'
def modulecards():return '<div class="module-grid">'+''.join('<article class="module-card" data-offer="O'+str(i+1)+'"><div class="module-top"><span>0'+str(i+1)+'</span><img src="/assets/icons/'+m['slug']+'.svg" alt="" width="32" height="32"></div><span class="eyebrow">'+m['verb']+'</span><h3>'+m['name']+'</h3><p>'+m['short']+'</p><div class="module-price">'+m['price']+' <small>'+m['unit']+'</small></div>'+link('/products/'+m['slug']+'/', 'Explore module ↗','text-link')+'<span class="small">Proposed module · price hypothesis</span></article>' for i,m in enumerate(MODULES))+'</div>'
def intro():return '''<section class="intro" aria-label="Watershed Observatory introduction"><video id="intro-video" muted playsinline preload="none" poster="/assets/intro-v2-poster.webp" aria-label="Illustrative reservoir intro; no real utility assets"><source data-src="/assets/intro-v2.mp4" type="video/mp4"></video><div class="intro-shade"></div><div class="intro-progress" aria-hidden="true"></div><div class="intro-copy"><span class="eyebrow">LEAKEVIDENCE / WATERSHED OBSERVATORY</span><p>Every district<br>has a <em>story.</em></p><span class="intro-sub">Bring the evidence into view.</span></div><div class="intro-end" aria-hidden="true"><span class="wordmark">LeakEvidence</span><p>Evidence informs. People decide.</p></div><div class="intro-controls"><span>Illustrative landscape · 8-second film</span><div><button id="intro-toggle" type="button">Play intro</button><a href="#hero" id="skip-intro">Skip intro ↓</a></div></div></section>'''
def home():
 hero='''<section class="atlas-hero" id="hero" tabindex="-1"><div class="hero-copy"><span class="eyebrow ruled">WATER-LOSS EVIDENCE FOR UTILITY TEAMS</span><h1>Separate suspected<br>leaks from verified<br>loss <em>before sending<br>a crew.</em></h1><p>Compare flow, pressure, acoustic and billing evidence. <br>Keep uncertainty visible, and the next decision <br>human-reviewed.</p><div class="actions">'''+button('/request-evaluation/?offer=undecided','Request a paid evaluation')+link('/demo/','Explore the simulated demo <span aria-hidden="true">→</span>','text-link')+'''</div><p class="micro">CONCEPT PREVIEW · NOT AN OPERATING PRODUCT</p></div><figure class="atlas-art"><img src="/assets/atlas-district-v2-transparent.png" alt="Engraved fictional district with river, bridge and underground green water main" width="1254" height="1254" fetchpriority="high"><a href="/demo/cases/demo-c01/" class="district-note"><span>DEMO · SIMULATED DATA</span><strong>District D07</strong><p>Suspected anomaly<br>Meter error not excluded<br>Field confirmation needed</p><small>Inspect the evidence →</small></a></figure><nav class="chapter-nav" aria-label="Homepage chapters"><a class="active" href="#hero">District</a><a href="#problem">Evidence</a><a href="#workbench">Review</a></nav></section>'''
