 problem='''<section class="anomaly-section" id="problem"><div class="wrap"><div class="anomaly-heading"><div><span class="eyebrow ruled">ILLUSTRATIVE EVIDENCE · NO LIVE CONTROLS</span><h2>One anomaly.<br><em>Three possible explanations.</em></h2></div><p>The same signal can have different causes.<br>Compare evidence across sources before<br>moving to field investigation.</p></div></div><div class="anomaly-stage"><figure class="sensor-art"><img src="/assets/atlas-sensors-v2.png" width="1536" height="1024" alt="Engraved water main with pressure, flow and acoustic sensors"><figcaption><span>Pressure<br>sensor</span><span>Flow<br>meter</span><span>Acoustic<br>sensor</span></figcaption></figure><div class="explanation-cards" role="group" aria-label="Compare explanations">'''+''.join('<button type="button" class="explanation-card '+('active' if key=='leak' else '')+'" data-explanation="'+key+'" aria-pressed="'+str(key=='leak').lower()+'"><span class="eyebrow">0'+str(i+1)+'</span><h3>'+title+'</h3><div class="mini-chart"><canvas data-chart="'+key+'" role="img" aria-label="'+title+' illustrative pattern"></canvas></div><p>'+desc+'</p><span class="card-action">Explore explanation <span>↗</span></span></button>' for i,(key,title,desc) in enumerate([('leak','Leakage','Sustained flow increase with acoustic activity may warrant investigation.'),('meter','Meter error','A step change in flow may reflect a meter-factor or calibration issue.'),('timing','Billing timing','A billing-window change may create an apparent accounting mismatch.')]))+'''</div></div><div class="wrap anomaly-bottom"><span class="eyebrow">THE REVIEW QUESTION</span><p id="explanation-note" aria-live="polite">The illustrative flow rise warrants review. Missing pressure and inconclusive acoustic evidence prevent confirmation.</p><a href="/demo/cases/demo-c01/" class="text-link">Inspect the source case →</a></div></section>'''
 offers='<section class="section atlas-offers" id="offers"><div class="wrap"><span class="eyebrow ruled">PROPOSED MODULES</span><div class="offers-heading"><h2>Five focused offers. <em>One evidence trail.</em></h2><p>Each module contributes to a clear evidence trail, from initial comparison to documented outcome.</p></div>'+modulecards()+'</div></section>'
 journey='<section class="journey" id="journey"><div class="journey-sticky"><div class="wrap journey-heading">'+tag('03 / FOLLOW THE EVIDENCE')+'<div class="row"><h2>From observation<br>to a reviewed next step.</h2><div class="journey-controls"><button data-journey="prev" aria-label="Previous evidence stage">←</button><span id="journey-count">01 / 05</span><button data-journey="next" aria-label="Next evidence stage">→</button></div></div></div><div class="journey-window"><div class="journey-track">'
 stages=[('Intake','Keep the source attached.','Observed time, recorded time and a named source. The case begins with provenance.','ledger'),('Exception','Let the gap remain a gap.','A missing pressure interval stays visible. It is never silently interpolated into certainty.','trend'),('Compare','Give alternatives equal space.','A suspected leak sits alongside meter error and a misaligned billing period.','proof'),('Review','A person owns the next step.','Record the reason, reviewer and dated task. Field authority remains with utility operators.','route'),('Export','Carry the context forward.','The packet leaves with its sources, uncertainty and synthetic-data label intact.','report')]
 for i,(name,title,desc,art) in enumerate(stages):journey+='<article class="journey-scene scene-'+str(i)+'"><div><span class="eyebrow">0'+str(i+1)+' / '+name+'</span><h3>'+title+'</h3><p>'+desc+'</p></div>'+artifact(art)+'</article>'
 journey+='</div></div></div></section>'
 platform=section('04 / THE SHARED WORKBENCH','See the district.<br><em>Read the case.</em>','<div class="split map-story"><div>'+district_visual()+'<div class="map-legend"><span>◇ Suspected</span><span>● Field-confirmed, simulated</span><span>— — Map exception</span></div></div><div>'+tag('DEMO-C01 / CEDAR REACH WATER UTILITY')+'<h3>Evidence support: moderate.</h3><p>An illustrative analyst assessment, not a calibrated probability. The pressure gap, unresolved meter factor and inconclusive acoustic note stay visible.</p><ul class="plain-list"><li>7 source items, with recording timestamps</li><li>1 missing pressure observation out of 8</li><li>No field-confirmation or repair record for C01</li></ul>'+button('/demo/cases/demo-c01/','Work the synthetic case')+'</div></div>','mist','workbench')
 roles=section('05 / ONE UTILITY BUYING GROUP','Shared evidence.<br><em>Different responsibilities.</em>','<div class="roles">'+''.join('<a href="'+url+'"><span class="eyebrow">'+n+'</span><h3>'+t+'</h3><p>'+d+'</p><span aria-hidden="true">↗</span></a>' for n,t,d,url in [('ACCOUNTABILITY','NRW manager','Reconcile the balance and define what the evaluation must prove.','/solutions/non-revenue-water/'),('OPERATIONS','Distribution director','Protect crew capacity with an explicit review and field-confirmation loop.','/solutions/distribution-operations/'),('DATA OWNERSHIP','Integration owner','Review permissions, source quality, AMI licenses and district boundaries.','/data-readiness/')])+'</div>')
 boundary=section('06 / A CLEAR BOUNDARY','Evidence informs.<br><em>Utility operators decide.</em>','<div class="boundary"><div><span class="eyebrow">LEAKEVIDENCE / READ-ONLY</span><ul><li>Compare sources</li><li>Retain alternatives</li><li>Prepare a review packet</li></ul></div><div class="boundary-divider">HUMAN<br>REVIEW</div><div><span class="eyebrow">UTILITY / FIELD AUTHORITY</span><ul><li>Authorize a visit</li><li>Isolate and excavate</li><li>Confirm and repair</li></ul></div></div><p class="boundary-note">No valve commands. No live writeback. No automatic dispatch.</p>'+link('/trust/','Read the scope and limitations ↗','text-link'),'dark','boundary')
 evidence=section('07 / WHAT THE PILOT WILL MEASURE','Proof has to be earned.','<div class="score-grid">'+''.join('<article><span class="eyebrow">'+n+'</span><h3>'+t+'</h3><p>'+d+'</p><span class="not-evaluated">Not yet evaluated</span></article>' for n,t,d in [('01','Precision at K','At an agreed crew-visit budget, compared with historical utility triage.'),('02','Avoided non-leak visits','Matched comparison, representative negatives and unresolved outcomes disclosed.'),('03','Verification burden','Crew time, data review and cost per adjudicated candidate.')])+'</div><p>No customer results or testimonials are claimed. Inspect the protocol before interpreting any future result.</p>'+link('/evaluation/','Explore the evaluation protocol ↗','text-link'),'olive')
 entry=section('08 / THE FIRST ENGAGEMENT','One district.<br><em>One carefully scoped test.</em>','<div class="split"><p class="large">Blind-rank known repaired leaks and representative false alerts, then agree a paid crew-supervised field validation.</p><div><p>A named sponsor, operator, data owner and crew lead. Authorized data sharing. A pre-registered comparator and cost of verification.</p>'+'<div class="engagement-actions">'+button('/pricing/','Review price hypotheses',True)+link('/data-readiness/','Check data readiness ↗','text-link')+'</div></div></div>','first-engagement','first-engagement')
 return intro()+hero+offers+problem+journey+platform+proof+roles+boundary+evidence+entry+section('09 / BEFORE WE BEGIN','Questions worth asking.',faq())+cta()

